from pathlib import Path
import re, html
root=Path('/tmp/converter-site')
base='https://convertforge.example'

tools=[]
def add(category, slug, title, frm, to, desc): tools.append(dict(category=category,slug=slug,title=title,frm=frm,to=to,desc=desc))
# Image
for a,b in [('jpg','png'),('png','jpg'),('jpg','webp'),('webp','jpg'),('png','webp'),('webp','png'),('jpeg','png'),('jpeg','webp'),('svg','png'),('svg','jpg'),('svg','webp'),('bmp','png'),('bmp','jpg'),('tiff','png'),('tiff','jpg'),('gif','png'),('gif','jpg'),('avif','png'),('avif','jpg'),('ico','png'),('heic','jpg')]:
 add('image',f'{a}-to-{b}',f'{a.upper()} to {b.upper()}',a.upper(),b.upper(),f'Convert {a.upper()} images to {b.upper()} online.')
# Document/data pages
for a,b in [('txt','pdf'),('jpg','pdf'),('png','pdf'),('webp','pdf'),('txt','html'),('txt','md'),('html','txt'),('html','md'),('md','html'),('json','csv'),('json','txt'),('csv','json'),('csv','txt'),('xml','txt'),('txt','json'),('html','pdf'),('docx','pdf'),('pdf','docx'),('docx','txt'),('pdf','txt'),('pptx','pdf'),('xlsx','csv'),('csv','xlsx'),('odt','pdf'),('rtf','pdf'),('epub','pdf')]:
 add('document',f'{a}-to-{b}',f'{a.upper()} to {b.upper()}',a.upper(),b.upper(),f'Convert {a.upper()} files to {b.upper()} with a clean, simple online workflow.')
# media / archive SEO pages
for a,b in [('mp4','mp3'),('mp4','webm'),('mov','mp4'),('avi','mp4'),('mkv','mp4'),('webm','mp4'),('wav','mp3'),('mp3','wav'),('flac','mp3'),('ogg','mp3'),('m4a','mp3'),('aac','mp3'),('mp4','gif'),('webm','gif'),('avi','gif'),('zip','tar'),('tar','zip'),('zip','7z'),('rar','zip'),('7z','zip')]:
 add('media',f'{a}-to-{b}',f'{a.upper()} to {b.upper()}',a.upper(),b.upper(),f'Convert {a.upper()} files to {b.upper()} online.')
# generic popular converters
for a,b in [('pdf','jpg'),('pdf','png'),('jpg','pdf'),('png','pdf'),('heic','png'),('heic','pdf'),('word','pdf'),('pdf','word'),('excel','csv'),('csv','excel'),('powerpoint','pdf'),('html','jpg'),('html','png')]:
 add('popular',f'{a}-to-{b}',f'{a.title()} to {b.upper()}',a.upper(),b.upper(),f'Fast {a.upper()} to {b.upper()} converter with drag-and-drop upload.')
# de-dupe slugs
seen=set(); tools=[t for t in tools if not (t['slug'] in seen or seen.add(t['slug']))]

def header(title,desc=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | ConvertForge</title><meta name="description" content="{html.escape(desc or title)}"><link rel="canonical" href="{base}/tools/PLACEHOLDER/"><link rel="stylesheet" href="/assets/style.css"></head><body><div class="topbar"><div class="container">Fast, simple online file conversion tools</div></div><nav class="nav"><div class="container navin"><a class="logo" href="/">Convert<span>Forge</span></a><div class="navlinks"><a href="/">Home</a><a href="/categories/">Categories</a><a href="/tools/">All Tools</a><a href="/about/">About</a><a href="/contact/">Contact</a></div><a class="btn mobile" href="/tools/">Tools</a></div></nav>'''
def footer(): return '''<footer class="footer"><div class="container footergrid"><div><h3>ConvertForge</h3><p>Useful online converters with a fast, focused interface. Browser-based tools run locally whenever practical.</p></div><div><h4>Converters</h4><a href="/categories/image/">Image</a><a href="/categories/document/">Document</a><a href="/categories/media/">Audio & Video</a></div><div><h4>Company</h4><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a></div><div><h4>Legal</h4><a href="/terms/">Terms</a><a href="/privacy/">Security & Privacy</a></div></div><div class="container copyright">© 2026 ConvertForge. All rights reserved.</div></footer><script src="https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script src="/assets/app.js"></script></body></html>'''

def converter_card(t):
 opts=''.join(f'<option value="{x}">{x.upper()}</option>' for x in sorted(set([t['to'].lower(),'png','jpg','webp','pdf','txt','json','csv','html','md'])))
 return f'''<div class="converter-card"><div class="drop"><input id="file" type="file"><strong>Drop your {t['frm']} file here</strong><small>or click to choose a file from your device</small></div><div class="fileinfo"></div><div class="controls"><div class="field"><label>From</label><input id="from" value="{t['frm']}" readonly></div><div class="field"><label>Convert to</label><select id="to">{opts}</select></div><button id="convert" class="btn">Convert</button></div><div class="status">Your file stays in your browser for supported local conversions.</div></div>'''

def tool_page(t):
 p=root/'tools'/t['slug'];p.mkdir(parents=True,exist_ok=True)
 body=header(t['title'],t['desc']).replace('PLACEHOLDER',t['slug'])
 body+=f'''<main class="container"><div class="tool-head"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/categories/{t['category']}/">{t['category'].title()}</a> / {t['title']}</div><h1>{html.escape(t['title'])}</h1><p>{html.escape(t['desc'])}</p></div>{converter_card(t)}<div class="notice">Privacy-first mode: supported image and text conversions are processed directly in your browser. Some document, audio, video and archive conversions require a server-side engine/API and are clearly reported instead of producing a fake file.</div><div class="ad">Advertisement</div><section class="section"><h2>How to convert {t['frm']} to {t['to']}</h2><div class="features"><div class="feature"><div class="icon">1</div><h3>Upload</h3><p>Choose your {t['frm']} file or drag it into the converter.</p></div><div class="feature"><div class="icon">2</div><h3>Choose output</h3><p>Select {t['to']} as the target format and start the conversion.</p></div><div class="feature"><div class="icon">3</div><h3>Download</h3><p>Download the converted file when the job finishes.</p></div></div></section><section class="section"><h2>Frequently asked questions</h2><div class="faq"><details open><summary>Is this {t['title']} converter free?</summary><p>Yes. ConvertForge is designed to provide free, straightforward online conversion tools.</p></details><details><summary>Are my files uploaded?</summary><p>Supported browser conversions are processed locally in your browser. Conversions that need a backend are not silently uploaded by this demo.</p></details><details><summary>What if my conversion is not supported?</summary><p>The converter will tell you when a server-side engine is required. The site architecture is ready for an API such as FFmpeg, LibreOffice or a commercial conversion API.</p></details></div></section></main>'''+footer()
 (p/'index.html').write_text(body)

for t in tools: tool_page(t)

# category pages
cats={'image':'Image Converters','document':'Document & Data Converters','media':'Audio & Video Converters','popular':'Popular Converters'}
for slug,name in cats.items():
 items=[t for t in tools if t['category']==slug]
 p=root/'categories'/slug;p.mkdir(parents=True,exist_ok=True)
 body=header(name,f'Browse free {name.lower()} on ConvertForge.').replace('PLACEHOLDER','categories/'+slug)
 cards=''.join(f'<a class="tool" data-tool href="/tools/{t["slug"]}/"><b>{html.escape(t["title"])}</b><span>{html.escape(t["desc"])}</span></a>' for t in items)
 body+=f'<main class="container"><div class="content"><div class="breadcrumbs"><a href="/">Home</a> / Categories / {name}</div><h1>{name}</h1><p>Explore dedicated, search-friendly converter pages with a consistent upload and conversion experience.</p><div class="ad">Advertisement</div><div class="grid">{cards}</div></div></main>'+footer()
 (p/'index.html').write_text(body)

# all tools
p=root/'tools';body=header('All Online Converters','Browse all ConvertForge conversion tools.').replace('PLACEHOLDER','tools')
cards=''.join(f'<a class="tool" data-tool href="/tools/{t["slug"]}/"><b>{html.escape(t["title"])}</b><span>{html.escape(t["desc"])}</span></a>' for t in tools)
body+=f'<main class="container"><div class="content"><div class="breadcrumbs"><a href="/">Home</a> / All Tools</div><h1>All Online Converters</h1><p>Search the converter library and open a dedicated tool.</p><div class="field" style="max-width:520px;margin:18px 0 25px"><label>Search converters</label><input id="siteSearch" placeholder="Try PDF to JPG, PNG to WEBP…"></div><div class="grid">{cards}</div></div></main>'+footer();(p/'index.html').write_text(body)

# static content
pages={'about':('About ConvertForge','ConvertForge is a practical online conversion toolkit focused on simple workflows and honest capability.','We build lightweight browser tools first, then connect heavier conversions to dedicated processing engines when needed.'),'contact':('Contact ConvertForge','Have a question, bug report, partnership request or conversion suggestion?','Email: hello@convertforge.example\nFor conversion bugs, include the tool URL, input format, output format and a short description of what happened.'),'privacy':('Privacy Policy','This privacy page explains how ConvertForge handles information.','Browser-only conversions are processed on your device when supported. If server-side conversion is added in the future, the relevant tool will disclose that processing before upload. We do not claim that unsupported conversions are private or local when they are not.'),'terms':('Terms of Use','Use ConvertForge responsibly and only with files you have the right to process.','The service is provided as-is. Always keep an original copy of important files. Conversion quality depends on the selected format and processing engine.')}
for slug,(title,desc,text) in pages.items():
 body=header(title,desc).replace('PLACEHOLDER',slug)
 body+=f'<main class="container"><div class="content"><div class="breadcrumbs"><a href="/">Home</a> / {title}</div><h1>{title}</h1><p>{desc}</p><div class="ad">Advertisement</div><h2>Our approach</h2><p>{text.replace(chr(10),"</p><p>")}</p><h2>Questions</h2><p>Use the contact page if you need help or want a new converter added.</p></div></main>'+footer();(root/slug/'index.html').write_text(body)

# homepage
cards=''.join(f'<a class="tool" data-tool href="/tools/{t["slug"]}/"><b>{html.escape(t["title"])}</b><span>{html.escape(t["desc"])}</span></a>' for t in tools[:20])
catcards=''.join(f'<a class="category" href="/categories/{slug}/"><strong>{name}</strong><span>{len([x for x in tools if x["category"]==slug])} tools</span></a>' for slug,name in cats.items())
body=header('Free Online File Converters','Convert images, documents, data, audio and video with simple online tools.').replace('PLACEHOLDER','')
body+=f'''<main><section class="hero"><div class="container"><span class="eyebrow">ALL-IN-ONE CONVERTER TOOLKIT</span><h1>Convert files online.<br>Simple. Fast. Honest.</h1><p>Convert images and common text/data formats directly in your browser, with a growing library of professional conversion tools.</p><a class="btn" href="/tools/">Browse all converters</a><div class="converter-card"><div class="drop"><input id="file" type="file"><strong>Drop a file to get started</strong><small>Choose a file and then select the output format</small></div><div class="fileinfo"></div><div class="controls"><div class="field"><label>From</label><input id="from" value="Auto-detect" readonly></div><div class="field"><label>Convert to</label><select id="to"><option value="png">PNG</option><option value="jpg">JPG</option><option value="webp">WEBP</option><option value="pdf">PDF</option><option value="txt">TXT</option><option value="json">JSON</option><option value="csv">CSV</option><option value="html">HTML</option></select></div><button id="convert" class="btn">Convert</button></div><div class="status">Your files remain local for supported browser conversions.</div></div></div></section><div class="container"><div class="ad">Advertisement</div></div><section class="section"><div class="container"><h2>Browse by category</h2><p class="section-intro">Start with a format family or jump directly into a popular converter.</p><div class="category-grid">{catcards}</div></div></section><section class="section"><div class="container"><h2>Popular converters</h2><p class="section-intro">Dedicated pages for high-intent searches and everyday file tasks.</p><div class="grid">{cards}</div><p style="margin-top:22px"><a class="btn secondary" href="/tools/">View all {len(tools)} tools</a></p></div></section><section class="section"><div class="container"><h2>Why use ConvertForge?</h2><div class="features"><div class="feature"><div class="icon">⚡</div><h3>Simple workflow</h3><p>Upload, choose an output, convert and download without a confusing dashboard.</p></div><div class="feature"><div class="icon">🔒</div><h3>Privacy-aware</h3><p>Supported browser conversions happen on your device instead of requiring a file upload.</p></div><div class="feature"><div class="icon">📚</div><h3>SEO-friendly tool library</h3><p>Every converter has its own page, explanation, FAQ and related category for easy discovery.</p></div></div></div></section><section class="section"><div class="container"><h2>Frequently asked questions</h2><div class="faq"><details open><summary>Can ConvertForge convert every file type?</summary><p>The library includes many conversion pages, but browser technology cannot safely perform every professional conversion. Unsupported heavy conversions are explicitly identified instead of generating invalid output.</p></details><details><summary>Do you store uploaded files?</summary><p>Browser-supported conversions do not require upload. If server-side processing is added for a tool, the page should clearly explain how that processing works.</p></details><details><summary>Can this site be monetized?</summary><p>Yes. The layout includes natural ad placements, high-intent SEO pages, category pages and related-tool navigation. Replace the advertisement placeholders with your approved ad network code.</p></details></div></div></section></main>'''+footer()
(root/'index.html').write_text(body)

# robots/sitemap
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://convertforge.example/sitemap.xml\n')
urls=['/','/tools/']+[f'/categories/{c}/' for c in cats]+[f'/{x}/' for x in pages]+[f'/tools/{t["slug"]}/' for t in tools]
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{base}{u}</loc></url>\n' for u in urls)+'</urlset>')
(root/'ads.txt').write_text('# Add your approved advertising network entries here.\n')
print('Generated',len(tools),'tool pages')
